-- State transitions declared for Item: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION catalog.items_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'discontinued'), ('active', 'inactive'), ('inactive', 'active'), ('inactive', 'discontinued'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: items.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_items__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS items_status_transition_check ON catalog.items;
CREATE TRIGGER items_status_transition_check
    BEFORE UPDATE OF "status" ON catalog.items
    FOR EACH ROW EXECUTE FUNCTION catalog.items_status_transition_check();
